macro_rules! deps {
    () => {
        Subscriber!();
    };
}

macro_rules! Id {
    () => {
        deps!();
        # [doc = " Identifies a span within the context of a subscriber."] # [doc = ""] # [doc = " They are generated by [`Subscriber`]s for each span as it is created, by"] # [doc = " the [`new_span`] trait method. See the documentation for that method for"] # [doc = " more information on span ID generation."] # [doc = ""] # [doc = " [`Subscriber`]: super::subscriber::Subscriber"] # [doc = " [`new_span`]: super::subscriber::Subscriber::new_span"] # [derive (Clone , Debug , PartialEq , Eq , Hash)] pub struct Id (NonZeroU64) ;
    };
}

Id!();